from pathlib import Path
import os,json,html,re
from urllib.parse import urlparse
root=Path(__file__).resolve().parents[1];public=root/'public';data=json.loads((root/'data/recipes.json').read_text())
origin=os.environ.get('SITE_ORIGIN','').strip().rstrip('/')
if origin and (urlparse(origin).scheme!='https' or urlparse(origin).path not in ('','/')):raise ValueError('SITE_ORIGIN must be https bare domain')
H=lambda s:html.escape(str(s),quote=True)
U={'g':'г','ml':'мл','pcs':'шт.','tsp':'ч. л.','tbsp':'ст. л.'}
P=re.compile(r'\{\{([a-z][a-z0-9_]*)(?::(0\.5|0\.25))?\}\}')
def amount(x,mult=1):
 v=round(x['amount']*mult,2);s=str(int(v)) if v.is_integer() else str(v).replace('.',',')
 return f'{s} {U[x["unit"]]}'
def photo(r):return f'<img src="/assets/{H(r["image"])}" alt="Иллюстративное изображение: {H(r["title"])}" loading="lazy" width="512" height="512">' if r.get('image') else '<div class="no-photo">✳ <span>Выпечка с заботой</span></div>'
def tags(r):return ''.join(f'<span class="tag">{H(t)}</span>' for t in r['tags'][:3])
