def doc(title,desc,path,body,ld=None):
 canonical=f'<link rel="canonical" href="{H(origin+path)}">' if origin else ''
 schema=('<script type="application/ld+json">'+json.dumps(ld,ensure_ascii=False).replace('</','<\\/')+'</script>') if ld else ''
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="yandex-verification" content="68cdd4d21d14995c"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8f5ee"><title>{H(title)}</title><meta name="description" content="{H(desc)}">{canonical}<link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><script defer src="/app.js"></script>{schema}</head><body id="top">{header()}{body}{footer()}</body></html>'''

